/**
 * Build WatchIn body from obixNetList and global config.
 *
 * - Reads controller host from global config
 * - Reads points from global.obixNetList[host].systems[*].label
 * - Builds <obj is="obix:WatchIn"><list name="add"><uri .../></list></obj>
 * - Sets msg.url, msg.headers and msg.controllerIp
 */
var config = global.get('config', 'persistent') || global.get('config') || {};

var scheme  = config.scheme  || "https";
var host    = config.host    || "127.0.0.1";
var port    = config.port    ? (":" + config.port) : "";
var baseUrl = config.baseUrl || "obix";

var ip = host; // key used in obixNetList
var net = global.get("obixNetList",'persistent') || {};
var controller = net[ip];

if (!controller || !controller.systems) {
    node.warn("No obixNetList.systems found for IP " + ip);
    return null;
}

// Collect all /out/ URIs from label
var labels = [];
Object.keys(controller.systems).forEach(function (sysName) {
    (controller.systems[sysName] || []).forEach(function (p) {
        if (p && p.label) labels.push(p.label);
    });
});

if (!labels.length) {
    node.warn("No points (labels) found in obixNetList for IP " + ip);
    return null;
}

// Build WatchIn body
var body = '<obj is="obix:WatchIn"><list name="add">';
labels.forEach(function (lbl) {
    body += '<uri val="' + lbl + '"/>';
});
body += '</list></obj>';

// HTTP config
msg.controllerIp = ip;
msg.headers = msg.headers || {};
msg.headers["Content-Type"] = "text/xml";

msg.url = scheme + "://" + host + "/"+ "obix/watchService/make/";
msg.method = "POST";
msg.payload = body;

// Cookie from login
var c = flow.get("niagaraCookie");
if (c) {
    msg.headers["Cookie"] = c;
}

return msg;

/**
 * Add Niagara cookie from flow context to the outgoing HTTP headers.
 *
 * Reads the cookie value stored in flow context under `niagaraCookie`
 * and adds it as a standard `Cookie` header if present.
 */
var c = flow.get("niagaraCookie");
msg.headers = msg.headers || {};
if (c) {
    msg.headers["Cookie"] = c;
}
return msg;

/**
 * Save watchUri (returned from /watchService/make/) into obixNetList[host].
 */
var config = global.get('config', 'persistent') || global.get('config') || {};
var ip = msg.controllerIp || config.host || "127.0.0.1";

var net = global.get("obixNetList",'persistent') || {};
if (!net[ip]) net[ip] = { systems: {} };

var root = msg.payload;
if (root && root.obj) root = root.obj;

var href = root && root.$ && root.$.href ? root.$.href : null;

if (!href) {
    node.warn("No href/watchUri found in watch make response");
} else {
    // Normalize to relative path: remove scheme+host
    href = href.replace(/^https?:\/\/[^/]+/, "");
    net[ip].watchUri = href;
    global.set("obixNetList", net,'persistent');
}

msg.payload = {
    controllerIp: ip,
    watchUri: net[ip].watchUri || null
};
return msg;

/**
 * Build watch add request using obixNetList and stored watchUri.
 *
 * POST to: <scheme>://<host>:<port><watchUri>/add/
 */
var config  = global.get('config', 'persistent') || global.get('config') || {};
var scheme  = config.scheme  || "https";
var host    = config.host    || "127.0.0.1";
var port    = config.port    ? (":" + config.port) : "";

var ip  = host;
var net = global.get("obixNetList",'persistent') || {};
var controller = net[ip];

if (!controller || !controller.systems || !controller.watchUri) {
    node.warn("Missing systems or watchUri for IP " + ip);
    return null;
}

// Base URL for this watch
var baseUrl = scheme + "://" + host  + controller.watchUri;
if (!/\/$/.test(baseUrl)) baseUrl += "/";
msg.url = baseUrl + "add/";

msg.method = "POST";
msg.headers = msg.headers || {};
msg.headers["Content-Type"] = "application/xml";

var c = flow.get("niagaraCookie");
if (c) {
    msg.headers["Cookie"] = c;
}

// Build <list name="hrefs"> with labels (relative URI to /out/)
var itemsXml = [];
var systems = controller.systems || {};

Object.keys(systems).forEach(function (sysName) {
    (systems[sysName] || []).forEach(function (p) {
        if (!p || !p.label) return;
        itemsXml.push('<uri val="' + p.label + '" />');
    });
});

if (itemsXml.length === 0) {
    node.warn("No points found to add to watch for IP " + ip);
}

msg.payload =
    '<obj is="obix:WatchIn">' +
      '<list name="hrefs">' +
        itemsXml.join("") +
      '</list>' +
    '</obj>';

return msg;

/**
 * Build watch pollRefresh request (initial values) using obixNetList and watchUri.
 */
var config  = global.get('config', 'persistent') || global.get('config') || {};
var scheme  = config.scheme  || "https";
var host    = config.host    || "127.0.0.1";
var port    = config.port    ? (":" + config.port) : "";

var ip  = host;
var net = global.get("obixNetList",'persistent') || {};
var controller = net[ip];

if (!controller || !controller.watchUri) {
    node.warn("Missing watchUri for IP " + ip);
    return null;
}

var baseUrl = scheme + "://" + host  + controller.watchUri; // e.g. /obix/watchService/watch19/
if (!/\/$/.test(baseUrl)) baseUrl += "/";
msg.url = baseUrl + "pollRefresh";  // important: pollRefresh for initial values

msg.method = "POST";
msg.headers = msg.headers || {};
msg.headers["Content-Type"] = "text/xml";

var c = flow.get("niagaraCookie");
if (c) {
    msg.headers["Cookie"] = c;
}

msg.controllerIp = ip;
msg.payload = "<obj/>";
msg.pollType = "refresh";
return msg;

/**
 * Extract `Set-Cookie` header from HTTP response and save it in flow context.
 *
 * Stored under: flow.set("niagaraCookie", allCookiesAsSingleString)
 * The node does not forward the original HTTP message; it only updates
 * the cookie store and then emits an empty message object.
 */
if (msg.headers && msg.headers["set-cookie"]) {
    var cookies = msg.headers["set-cookie"];
    if (!Array.isArray(cookies)) cookies = [cookies];
    var all = cookies.join("; ");
    flow.set("niagaraCookie", all);
    msg.payload = "Saved cookies: " + all;
} else {
    msg.payload = "No Set-Cookie header found in response.";
}

// This flow only cares about persisting the cookie; clear the message
// so downstream nodes start from a clean slate.
return msg = {};

/**
 * Update obixNetList inventory from WatchOut poll responses.
 *
 * Expected:
 *   - msg.payload is the XML->object representation of a WatchOut response
 *   - msg.controllerIp contains the Niagara controller IP
 *   - msg.pollType is "refresh" (full snapshot) or "changes" (delta)
 *
 * Behavior:
 *   - Updates global.obixNetList[ip].systems[system][i] with value, unit, and timestamps
 *   - Builds a per-poll structure of changed systems/points
 *   - For "refresh" polls, falls back to sending the full snapshot when no values are present
 *   - For "changes" polls, drops the message if there are no changed points
 */

var ip = msg.controllerIp;
var pollType = msg.pollType || "refresh";   // "refresh" or "changes"
var inv = global.get("obixNetList",'persistent') || {};
var host = inv[ip];

if (!host || !host.systems) {
    node.warn("No obixInventory.systems for IP " + ip);
    return msg;
}

// Collect only the points that change in this poll.
// Structure: { "VS3": [point1, point2, ...], "PC1": [ ... ] }
var changedSystems = {};

// --- Extract WatchOut root ---
var root = msg.payload;
if (root && root.obj) root = root.obj;

// --- Find list name="values" ---
var lists = root && root.list ? root.list : [];
if (!Array.isArray(lists)) lists = [lists];

var valuesList = null;
lists.forEach(function (l) {
    if (l && l.$ && l.$.name === "values") {
        valuesList = l;
    }
});

if (!valuesList) {
    node.debug("WatchOut without values list - no values/changes");
    if (pollType === "refresh") {
        // For refresh we still emit the full snapshot
        msg.payload = host.systems;
        return msg;
    } else {
        // For pollChanges without values: no changes -> nothing to forward
        return null;
    }
}

// --- Collect all elements in the values list (obj, bool, real, int, str) ---
var items = [];
["obj", "bool", "real", "int", "str"].forEach(function (k) {
    if (!valuesList[k]) return;
    var v = valuesList[k];
    if (!Array.isArray(v)) v = [v];
    items = items.concat(v);
});

if (!items.length) {
    node.debug("WatchOut values list is empty - no values/changes");
    if (pollType === "refresh") {
        msg.payload = host.systems;
        return msg;
    } else {
        return null;
    }
}

// --- Helper functions --------------------------------------------------------

function normalizeUri(u) {
    if (!u) return null;

    u = u.replace(/^https?:\/\/[^/]+/, "");

    // Decode %24 etc.
    try {
        u = decodeURIComponent(u);
    } catch (e) { }

    if (u && u[0] !== "/") u = "/" + u;
    return u;
}

function inferValueTypeFromTypeString(typeStr) {
    typeStr = typeStr || "";
    if (/Boolean/i.test(typeStr)) return "bool";
    if (/Numeric|Float|Double|Integer|Number/i.test(typeStr)) return "number";
    return "string";
}

// Map OBIX units to nicer symbols
function unitSymbolFromObixUnit(unit) {
    if (!unit) return null;
    var u = unit.toLowerCase();
    if (u.indexOf("celsius") !== -1) return "°C";
    if (u.indexOf("fahrenheit") !== -1) return "°F";
    if (u.indexOf("kelvin") !== -1) return "K";
    if (u.indexOf("percent") !== -1) return "%";
    if (u.indexOf("metre") !== -1 || u.indexOf("meter") !== -1) return "m";
    if (u.indexOf("second") !== -1) return "s";
    // Fallback: take the last part after '/'
    var parts = unit.split("/");
    return parts[parts.length - 1];
}

function castValue(point, rawValue) {
    var vType = (point && point.valueType) || inferValueTypeFromTypeString(point && point.type);

    if (vType === "bool") {
        if (typeof rawValue === "boolean") return rawValue;
        var s = String(rawValue).toLowerCase();
        return (s === "true" || s === "1" || s === "on");
    }

    if (vType === "number") {
        var n = Number(rawValue);
        if (!isNaN(n)) return n;
        // Fallback if conversion fails
        return rawValue;
    }

    // Default: string
    return String(rawValue);
}

function updatePointByUri(uri, rawValue, unitAttr) {
    uri = normalizeUri(uri);
    if (!uri) return;

    Object.keys(host.systems).forEach(function (sysName) {
        var arr = host.systems[sysName] || [];
        arr.forEach(function (p) {
            if (p.uri === uri) {
                var parsed = castValue(p, rawValue);
                var nowMs = Date.now();

                p.rawValue = rawValue;
                p.value = parsed;
                p.ts = nowMs;
                p.tsIso = new Date(nowMs).toISOString();

                // Update unit when we have information and the point is missing one
                if (unitAttr) {
                    p.unit = p.unit || unitAttr;
                    var sym = unitSymbolFromObixUnit(unitAttr);
                    p.unitSymbol = p.unitSymbol || sym;
                }

                // --- Mark the point as changed in this poll ---
                if (!changedSystems[sysName]) {
                    changedSystems[sysName] = [];
                }
                changedSystems[sysName].push(p);
            }
        });
    });
}

// --- Loop all items in the values list --------------------------------------

items.forEach(function (ch) {
    if (!ch) return;

    var pointUri = null;
    var rawValue = null;
    var unitAttr = null;

    // Most common case:
    //   <real ... href="..." val="35.0" unit="obix:units/celsius">
    // or:
    //   <bool ... href="..." val="false">
    if (ch.$) {
        if (ch.$.href) {
            pointUri = ch.$.href;
        }
        if (ch.$.val !== undefined) {
            rawValue = ch.$.val;
        }
        if (ch.$.unit) {
            unitAttr = ch.$.unit;
        }
    }

    // Fallback: <obj> with nested bool/real/int/str
    if (!pointUri && ch.ref) {
        var refs = ch.ref;
        if (!Array.isArray(refs)) refs = [refs];
        refs.forEach(function (r) {
            if (r.$ && r.$.href && !pointUri) {
                pointUri = r.$.href;
            }
        });
    }

    // If uri/value/unit are not on the top-level element, look for nested value nodes
    if (rawValue === null || !unitAttr) {
        ["bool", "real", "int", "str"].forEach(function (t) {
            if (rawValue !== null && unitAttr) return;
            var nodes = ch[t];
            if (!nodes) return;
            if (!Array.isArray(nodes)) nodes = [nodes];
            nodes.forEach(function (n) {
                if (!n || !n.$) return;
                if (rawValue === null && n.$.val !== undefined) {
                    rawValue = n.$.val;
                }
                if (!unitAttr && n.$.unit) {
                    unitAttr = n.$.unit;
                }
            });
        });
    }

    if (pointUri && rawValue !== null) {
        updatePointByUri(pointUri, rawValue, unitAttr);
    }
});

// Save inventory back to global context
inv[ip] = host;
global.set("obixNetList", inv,'persistent');

// If nothing actually changed in this poll:
if (!Object.keys(changedSystems).length) {
    if (pollType === "refresh") {
        // On refresh we can still send the full snapshot
        msg.payload = host.systems;
        return msg;
    } else {
        node.debug("No points changed in this poll");
        // For pollChanges: do not emit anything
        return null;
    }
}

// Decide what to emit
if (pollType === "refresh") {
    // Initial/periodic full read: all systems/points
    msg.payload = host.systems;
} else {
    // pollChanges: only systems/points that actually changed
    msg.payload = changedSystems;
}

return msg;

/**
 * Poll Scheduler
 *
 * - Reads global.get('config', 'persistent').pollingInterval (milliseconds or seconds)
 * - Controlled via msg.control: "start" | "stop" | "reload"
 * - Emits synthetic ticks: { topic: "poll", payload: Date.now() } at each interval
 */

const STORE = "persistent";
const cfg = global.get("config", STORE) || {};
let ms = Number(cfg.pollingInterval);

// Allow pollingInterval to be expressed in seconds when very small
if (Number.isFinite(ms) && ms > 0 && ms < 10_000) ms = ms * 1000;
// Fallback
if (!Number.isFinite(ms) || ms <= 0) ms = 60_000; // 60s default

let timer = context.get("pollTimer");

function startTimer() {
  if (timer) clearInterval(timer);
  timer = setInterval(() => {
    node.send({ topic: "poll", payload: Date.now() });
  }, ms);
  context.set("pollTimer", timer);
  node.status({ fill: "green", shape: "dot", text: `poll ${ms} ms` });
}

function stopTimer() {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
  context.set("pollTimer", null);
  node.status({ fill: "grey", shape: "ring", text: "stopped" });
}

const cmd = (msg.control || "").toLowerCase();
if (cmd === "stop")  { stopTimer(); return null; }
if (cmd === "start") { startTimer(); return null; }
if (cmd === "reload"){ startTimer(); return null; }

// Auto-start when no explicit command is provided
if (!timer) startTimer();

// This node produces its own ticks; incoming messages are ignored
return null;

/**
 * Build watch pollChanges request using obixNetList and stored watchUri.
 *
 * - Reads controller IP from global config (persistent)
 * - Resolves the controller entry in global.obixNetList
 * - Builds POST https://<ip><watchUri>/pollChanges with Niagara cookie
 */
var ip = global.get('config','persistent').host;
var inv = global.get("obixNetList",'persistent') || {};
var host = inv[ip];

if (!host || !host.watchUri) {
    node.warn("Missing watchUri for IP " + ip);
    return null;
}

var baseUrl = "https://" + ip + host.watchUri; // e.g. /obix/watchService/watch19/
if (!/\/$/.test(baseUrl)) baseUrl += "/";
msg.url = baseUrl + "pollChanges"; // .../watch19/pollChanges

msg.method = "POST";
msg.headers = msg.headers || {};
msg.headers["Content-Type"] = "text/xml";

var c = flow.get("niagaraCookie");
if (c) {
    msg.headers["Cookie"] = c;
}

msg.controllerIp = ip;
msg.payload = "<obj/>";
msg.pollType = "changes";
return msg;

/**
 * Fan out systems object into one message per point.
 *
 * Input:
 *   msg.payload = { <systemName>: [point, ...], ... }
 *
 * Behavior:
 *   - Only points where `toStream === true` are forwarded.
 *   - All other points are dropped (ignored).
 *
 * Output:
 *   An array of messages, one per point, with:
 *   - topic: "<system>/<name|component>"
 *   - payload: normalized telemetry envelope
 *   - meta: original point object
 */

// The systems object comes from "Update obixInventory" (either full snapshot or only changed systems)
var systems = msg.payload || {};
var out = [];

// Get job_uuid from config (prefer persistent store)
var cfg = global.get('config', 'persistent') || global.get('config') || {};
var job_uuid = cfg.JOB_UUID || cfg.jobUuid || null;

// Generate a timestamp for this batch
// (if you prefer unix ms → change to: var timeValue = Date.now();)
var timeValue = new Date().toISOString();

Object.keys(systems).forEach(function (sysName) {
    var arr = systems[sysName];

    if (!Array.isArray(arr)) return;

    arr.forEach(function (p) {
        // Drop if point is missing or not marked for streaming
        if (!p || p.toStream !== true) return;

        out.push({
            topic: sysName + "/" + (p.name || p.component || "unknown"),

            // Shaped payload
            payload: {
                job_uuid: job_uuid,
                time: timeValue,
                value: p.value,
                label: p.label || p.uri || (p.name || p.component || ""),
                hash: p.HASH || p.hash || null
            },

            // Keep meta so downstream consumers can still access raw point data
            meta: p
        });
    });
});

return [out];

/**
 * Periodic Tridium ping scheduler.
 *
 * - Uses a fixed interval (10 seconds) to generate synthetic "poll" messages.
 * - Each tick can be used to trigger a request towards Tridium (/obix/about)
 *   to keep the session and cookie alive.
 * - The timer can be controlled via msg.control: "start", "stop", "reload".
 */
let ms = Number(10000);

// Allow the value to be interpreted as seconds if very small (defensive)
if (Number.isFinite(ms) && ms > 0 && ms < 10_000) ms = ms * 1000;
// Fallback (60s) if configuration is invalid
if (!Number.isFinite(ms) || ms <= 0) ms = 60_000; // 60s default

let timer = context.get("pollTimer");

function startTimer() {
  if (timer) clearInterval(timer);
  timer = setInterval(() => {
    node.send({ topic: "poll", payload: Date.now() });
  }, ms);
  context.set("pollTimer", timer);
  node.status({ fill: "green", shape: "dot", text: `poll ${ms} ms` });
}

function stopTimer() {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
  context.set("pollTimer", null);
  node.status({ fill: "grey", shape: "ring", text: "stopped" });
}

const cmd = (msg.control || "").toLowerCase();
if (cmd === "stop")  { stopTimer(); return null; }
if (cmd === "start") { startTimer(); return null; }
if (cmd === "reload"){ startTimer(); return null; }

// Auto-start if no explicit command is provided
if (!timer) startTimer();

// The scheduler produces its own ticks; incoming messages are ignored
return null;

/**
 * Add Niagara cookie from flow context to the outgoing HTTP headers.
 *
 * Reads the cookie value stored in flow context under `niagaraCookie`
 * and adds it as a standard `Cookie` header if present.
 */
var c = flow.get("niagaraCookie");
msg.headers = msg.headers || {};
if (c) {
    msg.headers["Cookie"] = c;
}
return msg;

/**
 * Keepalive handler for Tridium /obix/about.
 *
 * - Updates the Niagara cookie in flow context when a new `Set-Cookie`
 *   header is received.
 * - Updates the node status to indicate the cookie was refreshed.
 * - Does not forward the message further in the flow.
 */
if (msg.headers && msg.headers["set-cookie"]) {
    var cookies = msg.headers["set-cookie"];
    if (!Array.isArray(cookies)) cookies = [cookies];
    var all = cookies.join("; ");
    flow.set("niagaraCookie", all);
    node.status({fill:"green", shape:"dot", text:"cookie refreshed"});
}
// Do not forward anything – this node is keepalive-only.
return null;

// --- Normalize & Annotate (standalone) -------------------------------------
// Purpose: Ensure consistent payload shape and metadata before downstream steps.
// - Rounds numeric values to two decimals (if present)
// - Sets input origin on payload
// - Ensures ISO-8601 timestamps
// - Maintains simple per-input ingress counters in persistent flow context
// ------------------------------------------------------------------------------

const inputName = (typeof msg.input === "string" && msg.input) || "unknown";

msg.payload = msg.payload || {};

// 1) Normalize numeric value (accepts both number and numeric string)
if (msg.payload.value != null) {
  const n = Number(msg.payload.value);
  if (Number.isFinite(n)) msg.payload.value = Math.round(n * 100) / 100;
}

// 2) Attach input annotations on payload for downstream visibility
msg.payload.input = inputName;
if (msg.payload.measuredValueType == null) msg.payload.measuredValueType = inputName;

// 3) Simple ingress metric per input (persistent)
const inKey = `incoming_count:${inputName}`;
let inCount = flow.get(inKey, "persistent");
if (typeof inCount !== "number") inCount = 0;
flow.set(inKey, inCount + 1, "persistent");

return msg;

// --- Count Outgoing (standalone) -------------------------------------------
// Purpose: Maintain a simple per-input egress counter in persistent flow context.
// This is useful for quick health/throughput checks without external tooling.
// ------------------------------------------------------------------------------

const inputName = (typeof msg.input === "string" && msg.input) || "unknown";
const outKey = `outgoing_count:${inputName}`;
let outCount = flow.get(outKey, "persistent");
if (typeof outCount !== "number") outCount = 0;
flow.set(outKey, outCount + 1, "persistent");
return msg;

// --- Drop: older-than-last-accepted (array context, 2 outputs, hash-based) ---
// Output 1: PASS (message continues)
// Output 2: AUDIT (diagnostic events for drops)
//
// Purpose
//   • Guard against out-of-order or replayed telemetry by dropping any record
//     whose timestamp is older than the *latest accepted* timestamp per key.
//   • Use a compact, append-only array in persistent flow context to limit
//     memory; periodically compacts to keep size bounded.
//
// Identity key
//   • Uses msg.payload.hash (or msg.payload.HASH). If missing, a deterministic
//     fallback is built from (inputName, sourceLabel, job_uuid), assigned back
//     to msg.payload.hash, and used for tracking.
// ------------------------------------------------------------------------------

const STORE      = "persistent";
const SCOPE      = "per_hash";   // "per_hash" | "per_input" | "global"
const MAX_LEN    = 4000;         // upper bound before compaction
const COMPACT_TO = 1500;         // target unique keys after compaction

// --- Helpers -----------------------------------------------------------------
function parseToMs(t) {
  if (t == null) return NaN;
  if (t instanceof Date) return t.getTime();
  if (typeof t === "number") {
    if (t > 1e12) return t;         // already in ms
    if (t > 1e9)  return t * 1000;  // seconds → ms
    return t;                        // assume ms
  }
  if (typeof t === "string") {
    const n = Number(t);
    if (Number.isFinite(n)) return parseToMs(n);
    const p = Date.parse(t);
    return Number.isNaN(p) ? NaN : p;
  }
  return NaN;
}

const normIso = (ms) => new Date(ms).toISOString();

function resolveInputName(msg) {
  return (
    (typeof msg.input === "string" && msg.input) ||
    (typeof msg?.payload?.input === "string" && msg.payload.input) ||
    msg?.topic ||
    "unknown"
  );
}

function scopeId(msg) {
  const inputName = resolveInputName(msg);
  if (SCOPE === "per_hash")  return `perHash:${inputName}`;
  if (SCOPE === "per_input") return `perInput:${inputName}`;
  return "global";
}

function keyFromMsg(msg) {
  const inputName = resolveInputName(msg);

  // Prefer hash/HASH; otherwise deterministic fallback for visibility & stability.
  let hash = (msg?.payload?.hash ?? msg?.payload?.HASH);
  if (!hash) {
    const sl = String(msg?.payload?.sourceLabel ?? "unknown");
    const ju = String(msg?.payload?.job_uuid    ?? "na");
    hash = `${inputName}:${sl}:${ju}`;
    if (msg?.payload) msg.payload.hash = hash;
  }
  return { inputName, hash: String(hash) };
}

function getArr(sid) {
  const k = `latestSeenArr:${sid}`;
  let arr = flow.get(k, STORE);
  if (!Array.isArray(arr)) arr = [];
  return { k, arr };
}

function latestForKey(arr, key) {
  for (let i = arr.length - 1; i >= 0; i--) {
    const row = arr[i];
    if (row && row[0] === key) return row[1];
  }
  return -Infinity;
}

function pushAndMaybeCompact(k, arr, key, ts) {
  arr.push([key, ts]);
  if (arr.length > MAX_LEN) {
    const seen = new Set();
    const compact = [];
    for (let i = arr.length - 1; i >= 0 && compact.length < COMPACT_TO; i--) {
      const row = arr[i]; if (!row) continue;
      const u = row[0];
      if (!seen.has(u)) { compact.push(row); seen.add(u); }
    }
    compact.reverse();
    arr = compact;
  }
  flow.set(k, arr, STORE);
}

// --- Main --------------------------------------------------------------------
msg.payload = msg.payload || {};

let incomingMs = parseToMs(msg.payload.time ?? msg.payload.timestamp ?? Date.now());
if (!Number.isFinite(incomingMs)) {
  node.status({ text: "drop (invalid time)" });
  let c = flow.get("dropped_invalid_time", STORE); if (typeof c !== "number") c = 0; flow.set("dropped_invalid_time", c+1, STORE);
  const audit = { payload: { outcome: "drop", reason: "INVALID_TIME", input: resolveInputName(msg) } };
  return [null, audit];
}
const iso = normIso(incomingMs);
msg.payload.time = iso;
msg.payload.timestamp = iso;

const { inputName, hash } = keyFromMsg(msg);
const sid = scopeId(msg);
const { k, arr } = getArr(sid);

// Choose lookup key by scope
const lookupKey =
  (SCOPE === "per_hash")  ? hash :
  (SCOPE === "per_input") ? "__input__" :
                            "__global__";

const lastMs = latestForKey(arr, lookupKey);

if (incomingMs < lastMs) {
  const lastIso = normIso(lastMs);
  const dk = `dropped_older_than_youngest:${inputName}`;
  let c = flow.get(dk, STORE); if (typeof c !== "number") c = 0; flow.set(dk, c+1, STORE);
  node.status({ text: `drop < ${lastIso}` });
  const audit = {
    payload: {
      outcome: "drop",
      reason: "OLDER_THAN_YOUNGEST",
      incomingIso: iso,
      lastAcceptedIso: lastIso,
      input: inputName,
      scope: SCOPE,
      key: lookupKey,
      hash
    }
  };
  return [null, audit];
}

// Accept and update latest time
pushAndMaybeCompact(k, arr, lookupKey, incomingMs);

let a = flow.get(`accepted_count:${inputName}`, STORE); if (typeof a !== "number") a = 0; flow.set(`accepted_count:${inputName}`, a+1, STORE);
node.status({ text: "ok (new or equal)" });
return [msg, null];
